import{_ as t,o,c as n,ab as r}from"./chunks/framework.Dmc_6vHW.js";const m=JSON.parse('{"title":"Development Environment","description":"","frontmatter":{"permalink":"/docs/development/development-environment/"},"headers":[],"relativePath":"docs/development/development-environment.md","filePath":"docs/development/development-environment.md"}'),a={name:"docs/development/development-environment.md"};function s(d,e,i,l,c,h){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="development-environment" tabindex="-1">Development Environment <a class="header-anchor" href="#development-environment" aria-label="Permalink to “Development Environment”">​</a></h1><h2 id="local-development" tabindex="-1">Local development <a class="header-anchor" href="#local-development" aria-label="Permalink to “Local development”">​</a></h2><p><strong>1) Setup SLM instance</strong> To setup a SLM instance with the latest snapshot version follow the <a href="/slm/docs/getting-started/installation.html">installation instructions</a> and use the latest snapshot version as tag or the SLM installer docker image (e.g. <code>ghcr.io/eclipse-slm/slm/installer:1.4.0-SNAPSHOT</code>).</p><p><strong>1) Export Configuration</strong></p><p>Edit the <code>stack/config-exporter/.env</code> file and set the following variable values according to your development setup:</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>LOCAL_PROJECT_PATH</code></td><td>Path to the checked out <a href="https://github.com/eclipse-slm/slm" target="_blank" rel="noreferrer">SLM git repository</a>. If you are using Docker Desktop for Windows add the above path in <code>Settings -&gt; Resources -&gt; FILE SHARING</code>.</td></tr><tr><td><code>SLM_HOSTNAME</code></td><td>Hostname of the host where your SLM instance is running.</td></tr><tr><td><code>LOCAL_HOSTNAME</code></td><td>Hostname of your local development machine.</td></tr><tr><td><code>CONSUL_SCHEME</code></td><td>Scheme of the host where the Consul instance of the SLM is running.</td></tr><tr><td><code>CONSUL_HOST</code></td><td>Hostname of the host where the Consul instance of the SLM is running.</td></tr><tr><td><code>CONSUL_PORT</code></td><td>Port of the host where the Consul instance of the SLM is running.</td></tr><tr><td><code>CONSUL_TOKEN</code></td><td>Master token of the Consul instance of your SLM instance. The Consul master token is printed at the end of the installer run or can be found under <code>/consul/config/local.json</code> in the consul container</td></tr></tbody></table><p>Run the config exporter using the following command inside the directory <code>stack/config-exporter</code>:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>docker-compose up</span></span></code></pre></div><p><strong>3) IDE</strong></p><p>Stop the containers relevant for your development and start the components in your IDE. Through the Config Exporter, your local project has been configured to allow the components started via IDE to connect to the locally deployed SLM instance.</p>',10)])])}const u=t(a,[["render",s]]);export{m as __pageData,u as default};
